using System.Reflection; using HarmonyLib; namespace PolyfishAI.src { public static class Dumper { public static void Dump() { PolyfishPlugin.Logger.LogInfo("Dumping Client..."); var gm = UnityEngine.Object.FindObjectOfType<GameManager>(); if (gm == null) { PolyfishPlugin.Logger.LogInfo("GM null"); return; } var client = gm.client; if (client == null) { PolyfishPlugin.Logger.LogInfo("Client is null!"); return; } var t = client.GetType(); foreach (var m in AccessTools.GetMethodNames(t)) { PolyfishPlugin.Logger.LogInfo("Client Method - " + m); } } } }
